 *
 * Renders the inline header row (title left — empty when there's no `title` text — close button
 * right) when either `title` or `boxedHeader` is passed, or a floating close button only when
 * neither is — see ZimmDrawer's own docblock for when each is used.
 *
 * @param props see ZimmDrawerContentConfig
 */
const ZimmDrawerContent = ({
  children,
  onClose,
  title,
  titleId,
  titleStyle = 'large',
  labelledBy,
  ariaLabel,
  boxedHeader,
  contentStyles,
  headerStyles,
  headerTitleStyles,
  closeButtonStyles,
  headerCloseButtonStyles,
